pm = <pluggy._manager.PluginManager object at 0x0000020D042D9D80>

    def test_call_order(pm: PluginManager) -> None:
        class Api:
            @hookspec
            def hello(self, arg):
                "api hook 1"

        pm.add_hookspecs(Api)

        class Plugin1:
            @hookimpl
            def hello(self, arg):
                return 1

        class Plugin2:
            @hookimpl
            def hello(self, arg):
                return 2

        class Plugin3:
            @hookimpl
            def hello(self, arg):
                return 3

        class Plugin4:
            @hookimpl(hookwrapper=True)
            def hello(self, arg):
                assert arg == 0
                outcome = yield
                assert outcome.get_result() == [3, 2, 1]
                assert outcome.exception is None
                assert outcome.excinfo is None

        pm.register(Plugin1())
        pm.register(Plugin2())
        pm.register(Plugin3())
        pm.register(Plugin4())  # hookwrapper should get same list result
>       res = pm.hook.hello(arg=0)

